        uint256 baseTarget = c._BASE_TARGET_();
        uint256 quoteTarget = c._QUOTE_TARGET_();

        // The invariant: baseTarget * quoteTokenBalance == quoteTarget * baseTokenBalance
        // This is a fundamental property of the PMM when no trading occurred
        assertTrue(baseTarget * quoteTokenBalance == quoteTarget * baseTokenBalance);
    }
